runHarness:
updateVideo("In draft", 10, "Draft Video")
  .then(res => console.log("Pass: Draft:", res))
  .catch(err => console.log("Fail: Draft:", err));

updateVideo("Published", 50, "New Upload")
  .then(res => console.log("Fail (should have rejected): Published (too early):", res))
  .catch(err => console.log("Pass: Published (too early):", err));

updateVideo("Published", 200, "Old Upload")
  .then(res => console.log("Pass: Published (old enough):", res))
  .catch(err => console.log("Fail: Published (old enough):", err));

updateVideo("Other", 20, "Random Video")
  .then(res => console.log("Success: Other:", res))
  .catch(err => console.log("Fail: Other:", err));

submitHarness:
async function runTests() {
  let passed = 0;
  let total = 0;

  async function test(
    name: string,
    fn: () => Promise<string>,
    expected: string,
    shouldReject: boolean = false
  ) {
    total++;
    try {
      const result = await fn();

      if (shouldReject) {
        console.log(`Fail: ${name} failed (expected rejection, got resolve)`);
        return;
      }

      if (result === expected) {
        console.log(`Pass: ${name} passed`);
        passed++;
      } else {
        console.log(`Fail: ${name} failed (wrong value)`);
        console.log("Expected:", expected);
        console.log("Got:", result);
      }
    } catch (err) {
      if (!shouldReject) {
        console.log(`Fail: ${name} failed (unexpected rejection)`);
        console.log("Error:", err);
        return;
      }

      if (err === expected) {
        console.log(`Pass: ${name} passed`);
        passed++;
      } else {
        console.log(`Fail: ${name} failed (wrong rejection value)`);
        console.log("Expected:", expected);
        console.log("Got:", err);
      }
    }
  }

  await test(
    "Draft resolves",
    () => updateVideo("In draft", 10, "Vid1"),
    "Succesfully updated video Vid1"
  );

  await test(
    "Published too early rejects",
    () => updateVideo("Published", 50, "Vid2"),
    "Video Vid2 hasn't been uploaded long enough to update.",
    true
  );

  await test(
    "Published old enough resolves",
    () => updateVideo("Published", 200, "Vid3"),
    "Published video Vid3 updated."
  );

  await test(
    "Exactly 100 should resolve",
    () => updateVideo("Published", 100, "EdgeVid"),
    "Published video EdgeVid updated."
  );

  await test(
    "Unknown status resolves",
    () => updateVideo("Private", 10, "OtherVid"),
    "Published video OtherVid updated."
  );

  console.log(`\n${passed}/${total} tests passed`);
}

runTests();
